BEGIN;
DO $qa$
DECLARE b1 uuid:=gen_random_uuid();b2 uuid:=gen_random_uuid();m uuid:=gen_random_uuid();c uuid:=gen_random_uuid();peer uuid:=gen_random_uuid();s uuid:=gen_random_uuid();cs uuid:=gen_random_uuid();d uuid:=gen_random_uuid();a uuid:=gen_random_uuid();k uuid:=gen_random_uuid();u uuid:=gen_random_uuid();x uuid:=gen_random_uuid();actor uuid;gid bigint;gid2 bigint;rev bigint;pub bigint;draft bigint;foreign_pub bigint;r jsonb;checks int:=0;cards jsonb:='[{"metric":"orders_today","label":"QA card","size":"wide","tone":"red","roles":["cashier"],"icon":"orders"}]';
BEGIN
 INSERT INTO auth.users(id) VALUES(m),(c),(peer),(s),(cs),(d),(a),(k),(u),(x);
 INSERT INTO public.ff_profiles(user_id,display_name,role,active) VALUES(m,'QA STEP12 design manager','manager',true),(c,'QA STEP12 design cashier','cashier',true),(peer,'QA STEP12 design peer','cashier',true),(s,'QA STEP12 design supervisor','supervisor',true),(cs,'QA STEP12 design CS','customer_service',true),(d,'QA STEP12 design driver','driver',true),(a,'QA STEP12 design assembly','assembly',true),(k,'QA STEP12 design kitchen','burger_kitchen',true),(x,'QA STEP12 design disabled','manager',false);
 PERFORM set_config('request.jwt.claim.sub',m::text,true);
 INSERT INTO public.ff_branches(id,code,name) VALUES(b1,'qa-step12-design-'||b1,'QA STEP12 design one'),(b2,'qa-step12-design-'||b2,'QA STEP12 design two');
 INSERT INTO public.ff_user_branches(user_id,branch_id) VALUES(c,b1),(peer,b2),(s,b1),(d,b1),(a,b1),(k,b1);
 SET LOCAL ROLE authenticated;PERFORM set_config('request.jwt.claim.sub',m::text,true);
 gid:=public.ff82_set_grant(c,b1,'cashier',ARRAY['view','edit','review'],now()-interval '1 minute',now()+interval '1 hour');IF gid IS NULL THEN RAISE EXCEPTION 'Manager grant failed';END IF;checks:=checks+1;
 gid2:=public.ff82_set_grant(peer,b2,'cashier',ARRAY['view','edit','review'],now()-interval '1 minute',now()+interval '1 hour');
 pub:=public.ff81_named_card_draft('cashier',b1,'mobile','D01','','labels','QA published','',cards);PERFORM public.ff_ui_publish(pub);
 draft:=public.ff81_named_card_draft('cashier',b1,'mobile','D02','','labels','QA unpublished','',cards);
 foreign_pub:=public.ff81_named_card_draft('cashier',b2,'mobile','D03','','labels','QA foreign','',cards);PERFORM public.ff_ui_publish(foreign_pub);
 IF pub IS NULL OR draft IS NULL OR foreign_pub IS NULL THEN RAISE EXCEPTION 'Missing legacy card revisions';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',c::text,true);
 r:=public.ff81_effective_design(b1,'mobile');IF r->>'id' IS DISTINCT FROM pub::text OR r->'card_layout' IS DISTINCT FROM cards THEN RAISE EXCEPTION 'Current effective design missing';END IF;checks:=checks+1;
 IF public.ff81_effective_cards(b1,'mobile',pub) IS DISTINCT FROM cards THEN RAISE EXCEPTION 'Current card layout missing';END IF;checks:=checks+1;
 IF public.ff81_effective_cards(b1,'mobile',draft) IS NOT NULL OR public.ff81_effective_cards(b1,'mobile',foreign_pub) IS NOT NULL THEN RAISE EXCEPTION 'Non-effective draft or foreign cards leaked';END IF;checks:=checks+1;
 BEGIN PERFORM public.ff81_effective_design(b2,'mobile');RAISE EXCEPTION 'Foreign design branch accepted' USING ERRCODE='ZQA12';EXCEPTION WHEN insufficient_privilege THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff81_effective_cards(b2,'mobile',foreign_pub);RAISE EXCEPTION 'Foreign card branch accepted' USING ERRCODE='ZQA12';EXCEPTION WHEN insufficient_privilege THEN NULL;END;checks:=checks+1;
 r:=public.ff82_delegate_draft('cashier.title','QA scoped text');rev:=(r->>'revision')::bigint;IF r->>'ok' IS DISTINCT FROM 'true' OR rev IS NULL THEN RAISE EXCEPTION 'Delegated draft lost';END IF;checks:=checks+1;
 IF NOT EXISTS(SELECT FROM public.ff82_delegate_history('cashier.title') j WHERE j.id=rev) THEN RAISE EXCEPTION 'Own draft history missing';END IF;checks:=checks+1;
 r:=public.ff82_delegate_review(rev,'QA own review');IF r->>'ok' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'Own review lost';END IF;checks:=checks+1;
 IF public.ff82_delegate_draft('login.title','QA outside scope')->>'ok' IS DISTINCT FROM 'false' OR EXISTS(SELECT FROM public.ff82_delegate_history('login.title')) THEN RAISE EXCEPTION 'Text scope escalation';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',peer::text,true);
 IF EXISTS(SELECT FROM public.ff82_delegate_history('cashier.title') j WHERE j.id=rev) OR public.ff82_delegate_review(rev,'QA foreign review')->>'ok' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'Other branch grant leaked';END IF;checks:=checks+1;
 FOREACH actor IN ARRAY ARRAY[c,s,cs,d,a,k,u,x] LOOP
  PERFORM set_config('request.jwt.claim.sub',actor::text,true);
  BEGIN PERFORM public.ff81_named_card_draft('cashier',b1,'mobile','D01','','labels','QA denied','',cards);RAISE EXCEPTION 'Unauthorized card draft' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL;END;checks:=checks+1;
  BEGIN PERFORM public.ff82_set_grant(c,b1,'cashier',ARRAY['view'],now(),now()+interval '1 hour');RAISE EXCEPTION 'Unauthorized grant' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL;END;checks:=checks+1;
  BEGIN PERFORM public.ff82_revoke_grant(gid);RAISE EXCEPTION 'Unauthorized revoke' USING ERRCODE='ZQA12';EXCEPTION WHEN SQLSTATE 'P0001' THEN NULL;END;checks:=checks+1;
 END LOOP;
 PERFORM set_config('request.jwt.claim.sub',m::text,true);
 IF public.ff82_revoke_grant(gid) IS DISTINCT FROM true THEN RAISE EXCEPTION 'Manager revoke lost';END IF;checks:=checks+1;
 PERFORM set_config('request.jwt.claim.sub',c::text,true);
 IF EXISTS(SELECT FROM public.ff82_delegate_history('cashier.title')) OR public.ff82_delegate_draft('cashier.title','QA revoked')->>'ok' IS DISTINCT FROM 'false' OR public.ff82_delegate_review(rev,'QA revoked review')->>'ok' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION 'Revocation not effective';END IF;checks:=checks+3;
 RESET ROLE;PERFORM set_config('request.jwt.claim.sub',m::text,true);
 UPDATE public.ff_profiles SET active=false WHERE user_id=c;
 SET LOCAL ROLE authenticated;PERFORM set_config('request.jwt.claim.sub',c::text,true);
 BEGIN PERFORM public.ff81_effective_design(b1,'mobile');RAISE EXCEPTION 'Disabled effective design accepted' USING ERRCODE='ZQA12';EXCEPTION WHEN insufficient_privilege THEN NULL;END;checks:=checks+1;
 BEGIN PERFORM public.ff81_effective_cards(b1,'mobile',pub);RAISE EXCEPTION 'Disabled effective cards accepted' USING ERRCODE='ZQA12';EXCEPTION WHEN insufficient_privilege THEN NULL;END;checks:=checks+1;
 RESET ROLE;
 IF (SELECT count(*) FROM public.ff82_content_reviews WHERE revision_id=rev)<>1 OR (SELECT count(*) FROM public.ff_content_versions WHERE actor_id=c AND branch_id=b1)<>1 OR (SELECT count(*) FROM public.ff_ui_versions WHERE branch_id IN(b1,b2))<>3 THEN RAISE EXCEPTION 'Unauthorized draft/review altered state';END IF;checks:=checks+1;
 IF checks<>43 THEN RAISE EXCEPTION 'Expected 43 assertions, got %',checks;END IF;
END $qa$;
SELECT 'PASS STEP12 legacy design and delegation: 43 assertions; current design/card isolation, grant scope, manager-only mutation, revocation, rollback' result;
ROLLBACK;
